      "fact_text": {
        "text": "Primitive type variables do not have members, so using the dot operator shows nothing.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Class types have members that can be accessed with the dot operator, such as System.out.printLine.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Primitive types store simple values, while reference types store complex objects.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Variables of primitive types are independent; changing the value of one does not affect another copy.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    }
  ],
  "explanations": [
    {
      "topic": {
        "text": "Dot operator usage",
        "refs": ["Q0000", "Q0001"]
      },
      "explanation_text": {
        "text": "The dot operator accesses members of an object; for primitive types it yields nothing because they have no members, whereas for class types it allows access to fields and methods.",
        "refs": ["Q0000", "Q0001"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Memory independence of primitive variables",
        "refs": ["Q0004"]
      },
      "explanation_text": {
        "text": "When a primitive variable is assigned to another, the two variables occupy separate memory locations, so modifying one does not affect the other.",
        "refs": ["Q0004"]
      },
      "explanation_type": null
    }
  ],
